package com.inventoryhighlight;

import lombok.AllArgsConstructor;
import lombok.Getter;

@Getter
@AllArgsConstructor
public enum FillStyle {
    BOX("Box", false),
    BACKGROUND("Background Only", true),
    ITEM_SILHOUETTE("Item Silhouette", true);

    private final String name;
    private final boolean spriteBased;

    @Override
    public String toString() {
        return name;
    }
}

package com.inventoryhighlight;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("inventoryhighlight")
public interface InventoryHighlightConfig extends Config {
    @ConfigSection(name = "General Settings", description = "General color settings", position = 1)
    String generalSection = "generalSection";

    @ConfigSection(name = "Hover Settings", description = "Hover highlight toggle, outlines, and fill appearance", position = 2)
    String hoverSection = "hoverSection";

    @ConfigSection(name = "Interaction Settings", description = "Configuration for active click press feedback, item selection flashing, and drop action highlighting", position = 3)
    String interactionSection = "interactionSection";

    @ConfigSection(name = "Bank Interface Settings", description = "Configuration for highlighting items inside the bank vault and bank inventory panel", position = 4)
    String bankSection = "bankSection";

    @ConfigSection(name = "Ignored Items Settings", description = "Configuration for excluding specific items by name from being highlighted", position = 5)
    String ignoredSection = "ignoredSection";

    // GENERAL SETTINGS
    @Alpha
    @ConfigItem(keyName = "hoverColor", name = "Highlight Color", description = "Main color used for hover highlights, active click feedback, and selection flashing", section = generalSection, position = 1)
    default Color hoverColor() {
        return new Color(0, 255, 255, 200); // Cyan Blue
    }

    // HOVER SETTINGS (Toggle + Outline + Fill)
    @ConfigItem(keyName = "highlightHover", name = "Enable Hover Highlight", description = "Toggles highlight overlay when hovering over inventory items", section = hoverSection, position = 1)
    default boolean highlightHover() {
        return true;
    }

    @ConfigItem(keyName = "enableOutline", name = "Enable Outline", description = "Toggles rendering of the outline border", section = hoverSection, position = 2)
    default boolean enableOutline() {
        return true;
    }

    @ConfigItem(keyName = "outlineStyle", name = "Outline Style", description = "Visual style of the outline border (Box, Corner Brackets, or Item Silhouette)", section = hoverSection, position = 3)
    default OutlineStyle outlineStyle() {
        return OutlineStyle.ITEM_SILHOUETTE;
    }

    @Range(min = 1, max = 5)
    @ConfigItem(keyName = "borderWidth", name = "Outline Width", description = "Thickness of the outline border in pixels (1 - 5)", section = hoverSection, position = 4)
    default int borderWidth() {
        return 1;
    }

    @ConfigItem(keyName = "enableFill", name = "Enable Fill", description = "Toggles rendering of the background fill", section = hoverSection, position = 5)
    default boolean enableFill() {
        return false;
    }

    @ConfigItem(keyName = "fillStyle", name = "Fill Style", description = "Visual style of the background fill (Box, Background Only, or Item Silhouette)", section = hoverSection, position = 6)
    default FillStyle fillStyle() {
        return FillStyle.ITEM_SILHOUETTE;
    }

    @Range(min = 10, max = 255)
    @ConfigItem(keyName = "fillOpacity", name = "Fill Opacity", description = "Opacity level for the background fill (10 - 255)", section = hoverSection, position = 7)
    default int fillOpacity() {
        return 65;
    }

    // INTERACTION SETTINGS (Click, Selection, & Drop)
    @ConfigItem(keyName = "highlightClick", name = "Enable Click Press Feedback", description = "Slightly insets (1px) and brightens the hover highlight during mouse press down for tactile click feedback", section = interactionSection, position = 1)
    default boolean highlightClick() {
        return true;
    }

    @ConfigItem(keyName = "enableSelectionFlash", name = "Enable Selection Flash", description = "Rhythmically flashes a background-only fill on and off once per game tick when an item is selected ('Use')", section = interactionSection, position = 2)
    default boolean enableSelectionFlash() {
        return true;
    }

    @ConfigItem(keyName = "enableDropHighlight", name = "Enable Drop Highlight", description = "Changes the highlight color when the default left-click action is 'Drop' (e.g. while holding Shift)", section = interactionSection, position = 3)
    default boolean enableDropHighlight() {
        return false;
    }

    @Alpha
    @ConfigItem(keyName = "dropColor", name = "Drop Color", description = "Color of the highlight overlay when the default left-click action is 'Drop'", section = interactionSection, position = 4)
    default Color dropColor() {
        return new Color(255, 50, 50, 200); // Vibrant Red
    }

    // BANK INTERFACE SETTINGS
    @ConfigItem(keyName = "highlightBank", name = "Enable Bank Highlight", description = "Toggles highlight overlay when hovering over items in the main bank vault or bank inventory panel", section = bankSection, position = 1)
    default boolean highlightBank() {
        return false;
    }

    @ConfigItem(keyName = "highlightBankPlaceholders", name = "Highlight Placeholders", description = "Whether to highlight empty bank placeholder items when bank highlighting is enabled", section = bankSection, position = 2)
    default boolean highlightBankPlaceholders() {
        return false;
    }

    // IGNORED ITEMS SETTINGS
    @ConfigItem(keyName = "enableIgnoredItems", name = "Enable Ignored Items", description = "Toggles ignoring specific item names from highlight overlays", section = ignoredSection, position = 1)
    default boolean enableIgnoredItems() {
        return false;
    }

    @ConfigItem(keyName = "ignoredItems", name = "Ignored Items", description = "Comma-separated list of item names to ignore from highlights. Supports '*' wildcards (case-insensitive, e.g. 'Coins, *bones, Rune*')", section = ignoredSection, position = 2)
    default String ignoredItems() {
        return "";
    }
}

package com.inventoryhighlight;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

public class InventoryHighlightOverlay extends WidgetItemOverlay {
    private static final long FLASH_HALF_TICK_MS = 300L;
    private static final int CLICK_PRESS_ALPHA_BOOST = 70;
    private static final int CLICK_PRESS_INSET_PX = 1;

    private final Client client;
    private final InventoryHighlightConfig config;
    private final ItemManager itemManager;
    private final InventoryHighlightRenderer renderer;

    private long lastGameTickTime = 0;
    private List<String> cachedIgnoredItems = Collections.emptyList();

    @Inject
    public InventoryHighlightOverlay(Client client, InventoryHighlightConfig config, ItemManager itemManager,
            InventoryHighlightRenderer renderer) {
        this.client = client;
        this.config = config;
        this.itemManager = itemManager;
        this.renderer = renderer;
        showOnInventory();
        showOnBank();
        updateIgnoredItemsCache();
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        lastGameTickTime = System.currentTimeMillis();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if ("inventoryhighlight".equals(event.getGroup()) && "ignoredItems".equals(event.getKey())) {
            updateIgnoredItemsCache();
        }
    }

    public void updateIgnoredItemsCache() {
        String rawInput = config.ignoredItems();
        if (rawInput == null || rawInput.trim().isEmpty()) {
            cachedIgnoredItems = Collections.emptyList();
        } else {
            cachedIgnoredItems = Text.fromCSV(rawInput);
        }
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget) {
        if (itemWidget == null || itemWidget.getWidget() == null) {
            return;
        }

        if (config.enableIgnoredItems()) {
            ItemComposition itemComp = itemManager.getItemComposition(itemId);
            if (itemComp != null && isItemIgnored(itemComp.getName())) {
                return;
            }
        }

        boolean isBankItem = WidgetUtil
                .componentToInterface(itemWidget.getWidget().getParentId()) == InterfaceID.BANKMAIN;

        // Check Bank Interface configuration settings
        if (isBankItem) {
            if (!config.highlightBank()) {
                return;
            }
            boolean isPlaceholder = itemWidget.getQuantity() == 0;
            if (isPlaceholder && !config.highlightBankPlaceholders()) {
                return;
            }
        }

        // Check if mouse button is actively pressed down
        boolean isMouseDown = client.getMouseCurrentButton() != 0;
        Widget draggedWidget = client.getDraggedWidget();

        // 1. Permanent drag and fast mouse swipe suppression
        if (isMouseDown && (client.isDraggingWidget() || draggedWidget != null)) {
            if (draggedWidget == null || draggedWidget.getIndex() != itemWidget.getWidget().getIndex()) {
                return;
            }
        }

        Rectangle bounds = itemWidget.getCanvasBounds();
        if (bounds == null) {
            return;
        }

        // 2. Selection state highlight ("Use Item -> ...")
        boolean isSelected = client.isWidgetSelected()
                && client.getSelectedWidget() != null
                && client.getSelectedWidget().equals(itemWidget.getWidget());

        if (isSelected) {
            if (config.enableSelectionFlash()) {
                // Game Tick Synchronized Flash Cycle: ON for first 300ms of game tick, OFF for
                // second 300ms
                long timeInTick = lastGameTickTime > 0 ? (System.currentTimeMillis() - lastGameTickTime) : 0;
                boolean flashVisible = (timeInTick < FLASH_HALF_TICK_MS);

                if (flashVisible) {
                    renderer.renderSelectionHighlight(graphics, bounds, itemId, itemWidget.getQuantity(),
                            config.hoverColor(), config, itemManager);
                }
            }
            return;
        }

        // 3. Right-click menu locking and suppression while menu remains open
        if (client.isMenuOpen()) {
            Menu menu = client.getMenu();
            if (menu != null) {
                MenuEntry[] entries = menu.getMenuEntries();
                if (entries != null && entries.length > 0) {
                    int targetSlot = getRightClickedInventorySlot(entries, itemWidget.getWidget().getParentId());
                    if (targetSlot >= 0) {
                        if (itemWidget.getWidget().getIndex() == targetSlot) {
                            Color activeColor = getActiveHighlightColor();
                            if (activeColor != null) {
                                renderer.renderHighlight(graphics, bounds, itemId, itemWidget.getQuantity(),
                                        activeColor, config, itemManager);
                            }
                        }
                        return; // Suppress hover highlight on all other inventory/bank slots while menu is open
                    }
                }
            }
            return; // Suppress hover highlight while any non-inventory/bank menu is open
        }

        // 4. Hover and active click highlight
        if (!isBankItem && !config.highlightHover()) {
            return;
        }

        Point mousePt = client.getMouseCanvasPosition();
        if (mousePt == null || !bounds.contains(mousePt.getX(), mousePt.getY())) {
            return;
        }

        Color activeColor = getActiveHighlightColor();
        if (activeColor == null) {
            return;
        }

        if (isMouseDown && config.highlightClick()) {
            // 1-pixel inset bounds for tactile "button press" click effect
            Rectangle clickBounds = new Rectangle(
                    bounds.x + CLICK_PRESS_INSET_PX,
                    bounds.y + CLICK_PRESS_INSET_PX,
                    Math.max(1, bounds.width - (CLICK_PRESS_INSET_PX * 2)),
                    Math.max(1, bounds.height - (CLICK_PRESS_INSET_PX * 2)));

            // Boost alpha for brighter/more solid click press color
            int pressAlpha = Math.min(255, activeColor.getAlpha() + CLICK_PRESS_ALPHA_BOOST);
            Color pressColor = new Color(activeColor.getRed(), activeColor.getGreen(), activeColor.getBlue(),
                    pressAlpha);

            renderer.renderHighlight(graphics, clickBounds, itemId, itemWidget.getQuantity(), pressColor, config,
                    itemManager);
        } else {
            renderer.renderHighlight(graphics, bounds, itemId, itemWidget.getQuantity(), activeColor, config,
                    itemManager);
        }
    }

    private int getRightClickedInventorySlot(MenuEntry[] entries, int containerParentId) {
        for (int i = entries.length - 1; i >= 0; i--) {
            MenuEntry entry = entries[i];
            if (entry != null && entry.getWidget() != null && entry.getWidget().getId() == containerParentId) {
                return entry.getParam0(); // param0 is item slot index
            }
        }
        return -1;
    }

    Color getActiveHighlightColor() {
        return (isDropAction() && config.enableDropHighlight())
                ? config.dropColor()
                : config.hoverColor();
    }

    boolean isDropAction() {
        Menu menu = client.getMenu();
        if (menu != null) {
            MenuEntry[] menuEntries = menu.getMenuEntries();
            if (menuEntries != null && menuEntries.length > 0) {
                MenuEntry top = menuEntries[menuEntries.length - 1];
                return top != null && "Drop".equalsIgnoreCase(top.getOption());
            }
        }
        return false;
    }

    boolean isItemIgnored(String itemName) {
        if (itemName == null || itemName.isEmpty() || cachedIgnoredItems.isEmpty()) {
            return false;
        }

        for (String pattern : cachedIgnoredItems) {
            if (WildcardMatcher.matches(pattern, itemName)) {
                return true;
            }
        }

        return false;
    }
}

package com.inventoryhighlight;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Inventory Interaction Highlight",
    description = "Highlight inventory items during hover, active click, and selection states",
    tags = {"inventory", "item", "hover", "click", "highlight", "overlay", "selection"}
)
public class InventoryHighlightPlugin extends Plugin {
    @Inject
    private OverlayManager overlayManager;

    @Inject
    private EventBus eventBus;

    @Inject
    private InventoryHighlightOverlay overlay;

    @Override
    protected void startUp() throws Exception {
        overlayManager.add(overlay);
        eventBus.register(overlay);
        log.info("Inventory Interaction Highlight plugin started successfully.");
    }

    @Override
    protected void shutDown() throws Exception {
        eventBus.unregister(overlay);
        overlayManager.remove(overlay);
        log.info("Inventory Interaction Highlight plugin stopped.");
    }

    @Provides
    InventoryHighlightConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(InventoryHighlightConfig.class);
    }
}

package com.inventoryhighlight;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.concurrent.TimeUnit;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class InventoryHighlightRenderer {
    private static final int CACHE_MAX_SIZE = 500;
    private static final int CACHE_EXPIRATION_MINUTES = 10;
    private static final int MAX_TEXT_SCAN_HEIGHT = 12;

    // High-performance Guava sprite cache (caches rendered fills and outlines)
    private final Cache<String, BufferedImage> spriteCache = CacheBuilder.newBuilder()
            .maximumSize(CACHE_MAX_SIZE)
            .expireAfterAccess(CACHE_EXPIRATION_MINUTES, TimeUnit.MINUTES)
            .build();

    // High-performance Guava mask cache (caches 2D text pixel masks on cache misses)
    private final Cache<String, boolean[][]> maskCache = CacheBuilder.newBuilder()
            .maximumSize(CACHE_MAX_SIZE)
            .expireAfterAccess(CACHE_EXPIRATION_MINUTES, TimeUnit.MINUTES)
            .build();

    public static boolean isSpriteBased(FillStyle style) {
        return style != null && style.isSpriteBased();
    }

    public static boolean isSpriteBased(OutlineStyle style) {
        return style != null && style.isSpriteBased();
    }

    public void renderHighlight(Graphics2D graphics, Rectangle bounds, int itemId, int quantity,
            Color color, InventoryHighlightConfig config, ItemManager itemManager) {
        Stroke oldStroke = graphics.getStroke();
        Color oldColor = graphics.getColor();

        // 1. Render Fill (Background Layer)
        if (config.enableFill()) {
            renderFill(graphics, bounds, itemId, quantity, color, config.fillStyle(), config.fillOpacity(),
                    itemManager);
        }

        // 2. Render Outline (Border Layer on top of Fill)
        if (config.enableOutline()) {
            renderOutline(graphics, bounds, itemId, quantity, color, config.outlineStyle(), config.borderWidth(),
                    itemManager);
        }

        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
    }

    public void renderSelectionHighlight(Graphics2D graphics, Rectangle bounds, int itemId, int quantity,
            Color hoverColor, InventoryHighlightConfig config, ItemManager itemManager) {
        if (hoverColor == null) {
            return;
        }

        int opacity = config.enableFill() ? Math.min(255, Math.max(0, config.fillOpacity())) : 65;
        Color fillColor = new Color(hoverColor.getRed(), hoverColor.getGreen(), hoverColor.getBlue(), opacity);

        // Selection Flash ALWAYS uses Background Only Fill (zero outlines to avoid 3D mesh conflicts)
        renderSpriteFill(graphics, bounds, itemId, quantity, fillColor, FillStyle.BACKGROUND, itemManager);
    }

    private void renderFill(Graphics2D graphics, Rectangle bounds, int itemId, int quantity, Color baseColor,
            FillStyle style, int rawOpacity, ItemManager itemManager) {
        if (style == null) {
            return;
        }

        int opacity = Math.min(255, Math.max(0, rawOpacity));
        Color fillColor = new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), opacity);

        if (style.isSpriteBased()) {
            renderSpriteFill(graphics, bounds, itemId, quantity, fillColor, style, itemManager);
            return;
        }

        switch (style) {
            case BOX:
                graphics.setColor(fillColor);
                graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
                break;

            default:
                log.warn("Unhandled vector fill style: {}", style);
                break;
        }
    }

    private void renderSpriteFill(Graphics2D graphics, Rectangle bounds, int itemId, int quantity,
            Color fillColor, FillStyle style, ItemManager itemManager) {
        String key = style.name().toLowerCase() + "_" + itemId + "_" + quantity + "_" + fillColor.getRGB();
        BufferedImage cached = spriteCache.getIfPresent(key);

        if (cached == null) {
            cached = generateSpriteFill(itemId, quantity, fillColor, style, itemManager);
            if (cached != null) {
                spriteCache.put(key, cached);
            }
        }

        if (cached != null) {
            graphics.drawImage(cached, bounds.x, bounds.y, null);
        }
    }

    private BufferedImage generateSpriteFill(int itemId, int quantity, Color fillColor, FillStyle style,
            ItemManager itemManager) {
        ItemComposition itemComp = itemManager.getItemComposition(itemId);
        boolean isStack = quantity > 1 || (itemComp != null && itemComp.isStackable());

        BufferedImage itemImg = isStack
                ? itemManager.getImage(itemId, quantity, true)
                : itemManager.getImage(itemId, 1, false);

        if (itemImg == null) {
            return null;
        }

        AlphaComposite composite;
        switch (style) {
            case ITEM_SILHOUETTE:
                composite = AlphaComposite.DstIn;
                break;

            case BACKGROUND:
                composite = AlphaComposite.DstOut;
                break;

            default:
                log.warn("Unhandled sprite fill style: {}", style);
                return null;
        }

        int width = itemImg.getWidth();
        int height = itemImg.getHeight();
        BufferedImage buffer = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = buffer.createGraphics();

        g.setColor(fillColor);
        g.fillRect(0, 0, width, height);
        g.setComposite(composite);
        g.drawImage(itemImg, 0, 0, null);
        g.dispose();

        applyTextMaskIfStack(buffer, isStack, itemId, quantity, itemManager);

        return buffer;
    }

    private void renderOutline(Graphics2D graphics, Rectangle bounds, int itemId, int quantity, Color color,
            OutlineStyle style, int rawWidth, ItemManager itemManager) {
        if (style == null) {
            return;
        }

        int borderWidth = Math.max(1, rawWidth);

        switch (style) {
            case ITEM_SILHOUETTE:
                renderSilhouetteOutline(graphics, bounds, itemId, quantity, color, borderWidth, itemManager);
                break;

            case CORNER_BRACKETS:
                renderCornerBrackets(graphics, bounds, color, borderWidth);
                break;

            case BOX:
                renderBoxOutline(graphics, bounds, color, borderWidth);
                break;

            default:
                log.warn("Unhandled outline style: {}", style);
                break;
        }
    }

    private void renderSilhouetteOutline(Graphics2D graphics, Rectangle bounds, int itemId, int quantity,
            Color color, int borderWidth, ItemManager itemManager) {
        BufferedImage outline = getSilhouetteOutline(itemId, quantity, color, borderWidth, itemManager);
        if (outline != null) {
            graphics.drawImage(outline, bounds.x, bounds.y, null);
        }
    }

    private BufferedImage getSilhouetteOutline(int itemId, int quantity, Color color, int borderWidth,
            ItemManager itemManager) {
        String key = "outline_silhouette_" + itemId + "_" + quantity + "_" + borderWidth + "_" + color.getRGB();
        BufferedImage cached = spriteCache.getIfPresent(key);
        if (cached != null) {
            return cached;
        }

        BufferedImage baseOutline = itemManager.getItemOutline(itemId, quantity, color);
        if (baseOutline == null) {
            return null;
        }

        ItemComposition itemComp = itemManager.getItemComposition(itemId);
        boolean isStack = quantity > 1 || (itemComp != null && itemComp.isStackable());

        if (borderWidth == 1 && !isStack) {
            spriteCache.put(key, baseOutline);
            return baseOutline;
        }

        int width = baseOutline.getWidth();
        int height = baseOutline.getHeight();
        BufferedImage outlineBuffer = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = outlineBuffer.createGraphics();

        g.drawImage(baseOutline, 0, 0, null);
        for (int b = 1; b < borderWidth; b++) {
            g.drawImage(baseOutline, -b, 0, null);
            g.drawImage(baseOutline, b, 0, null);
            g.drawImage(baseOutline, 0, -b, null);
            g.drawImage(baseOutline, 0, b, null);
        }
        g.dispose();

        applyTextMaskIfStack(outlineBuffer, isStack, itemId, quantity, itemManager);

        spriteCache.put(key, outlineBuffer);
        return outlineBuffer;
    }

    private void renderCornerBrackets(Graphics2D graphics, Rectangle bounds, Color color, int borderWidth) {
        graphics.setColor(color);
        graphics.setStroke(new BasicStroke(borderWidth));
        int len = Math.min(8, Math.min(bounds.width, bounds.height) / 3);

        int x = bounds.x;
        int y = bounds.y;
        int right = x + bounds.width - 1;
        int bottom = y + bounds.height - 1;

        // Top-Left Corner
        graphics.drawLine(x, y, x + len, y);
        graphics.drawLine(x, y, x, y + len);

        // Top-Right Corner
        graphics.drawLine(right, y, right - len, y);
        graphics.drawLine(right, y, right, y + len);

        // Bottom-Left Corner
        graphics.drawLine(x, bottom, x + len, bottom);
        graphics.drawLine(x, bottom, x, bottom - len);

        // Bottom-Right Corner
        graphics.drawLine(right, bottom, right - len, bottom);
        graphics.drawLine(right, bottom, right, bottom - len);
    }

    private void renderBoxOutline(Graphics2D graphics, Rectangle bounds, Color color, int borderWidth) {
        graphics.setColor(color);
        graphics.setStroke(new BasicStroke(borderWidth));
        graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
    }

    private void applyTextMaskIfStack(BufferedImage sprite, boolean isStack, int itemId, int quantity,
            ItemManager itemManager) {
        if (isStack && sprite != null) {
            boolean[][] textPixelMask = getTextPixelMask(itemId, quantity, itemManager);
            if (textPixelMask != null) {
                applyTextMask(sprite, sprite.getWidth(), sprite.getHeight(), textPixelMask);
            }
        }
    }

    private boolean[][] getTextPixelMask(int itemId, int quantity, ItemManager itemManager) {
        String maskKey = "mask_" + itemId + "_" + quantity;
        boolean[][] cachedMask = maskCache.getIfPresent(maskKey);
        if (cachedMask != null) {
            return cachedMask;
        }

        BufferedImage baseImg = itemManager.getImage(itemId, quantity, false);
        BufferedImage textImg = itemManager.getImage(itemId, quantity, true);

        if (baseImg == null || textImg == null) {
            return null;
        }

        int width = textImg.getWidth();
        int height = textImg.getHeight();

        if (baseImg.getWidth() != width || baseImg.getHeight() != height) {
            return null;
        }

        boolean[][] mask = new boolean[height][width];
        int scanHeight = Math.min(MAX_TEXT_SCAN_HEIGHT, height);

        for (int y = 0; y < scanHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (textImg.getRGB(x, y) != baseImg.getRGB(x, y)) {
                    mask[y][x] = true; // Mark pixel as text pixel
                }
            }
        }

        maskCache.put(maskKey, mask);
        return mask;
    }

    private void applyTextMask(BufferedImage sprite, int width, int height, boolean[][] textPixelMask) {
        int scanHeight = Math.min(MAX_TEXT_SCAN_HEIGHT, Math.min(height, textPixelMask.length));
        for (int y = 0; y < scanHeight; y++) {
            int scanWidth = Math.min(width, textPixelMask[y].length);
            for (int x = 0; x < scanWidth; x++) {
                if (textPixelMask[y][x]) {
                    sprite.setRGB(x, y, 0); // Make text character pixel transparent for all fill and outline modes
                }
            }
        }
    }
}

